"""Shared logic of the RC training package, first batch: run specs, paths, nnU-Net command and environment, the
/dev/shm copy, log parsing and projections. Nothing here imports torch or nnU-Net, so the local unit tests run
without them.

Derived from s2_p3_wave2_20261104_r5/runtime/p3.py. Changed:
- every run starts from the M checkpoint of its fold in the r5 package (source_checkpoint; read only, pinned in
  RUN.json source_package), not from a run of this package;
- rc_env: the variables the RC trainers read (the M checkpoint; the case lists for B0', BU and BUL);
- val_count: runs with "cohort": "ucsd" validate the UCSD cases of the fold only (count from the case lists);
- no conditional runs; the trainers' smoke-only variables are added to P3_ENV;
- the smoke stage is a CPU smoke (cpu_smoke.py): its command carries "-device cpu", its environment the two
  smoke-only overrides (2 epochs of a few iterations), and it validates the two cases the preflight chose
  (smoke_val_cases).
"""

from __future__ import annotations

import os
import re
import shutil
import statistics
import time
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Sequence

import common as C

RUN = C.load_run()
TREE = Path(RUN["tree"])
RAW, PRE = TREE / "nnUNet_raw", TREE / "nnUNet_preprocessed"
CONFIG = RUN["configuration"]
DATA_ID = RUN["data_identifier"]
EXT = C.ROOT / "runtime" / "ext"
RAW_EMPTY = C.ROOT / "nnunet_env" / "raw_empty"
STAGES = ("smoke", "train")
SHM_DIRS = ("gt_segmentations", DATA_ID)  # the only folders of a preprocessed dataset; everything else is top-level JSON
CACHE_KEYS = ("MPLCONFIGDIR", "TRITON_CACHE_DIR", "TORCHINDUCTOR_CACHE_DIR", "XDG_CACHE_HOME", "CUDA_CACHE_PATH")
# The variables that select a run's behaviour inside the trainers; real runs must not inherit any of them.
P3_ENV = ("P3_SMOKE_EPOCHS", "P3_CONTINUE_FROM", "P3_CONTINUE_SOURCE_EPOCH", "P3_CONTINUE_SOURCE_SHA256",
          "RC_SMOKE_ITERATIONS", "RC_SOURCE_CHECKPOINT", "RC_SOURCE_EPOCH", "RC_SOURCE_SHA256", "RC_CASE_LISTS",
          "RC_CASE_LISTS_SHA256")
CASE_LISTS = C.ROOT / "evidence" / "RC_CASE_LISTS.json"  # written once by the preflight, never changed afterwards

# nnU-Net's print_to_log_file writes "<datetime>: " + each argument followed by one space; str(datetime) drops the
# fraction when the microseconds happen to be 0.
TS = r"\d{4}-\d\d-\d\d \d\d:\d\d:\d\d(?:\.\d+)?"
STAMP = re.compile(rf"^({TS}): ")
EPOCH_START = re.compile(rf"^({TS}): Epoch (\d+)\s*$")
EPOCH_TIME = re.compile(rf"^{TS}: Epoch time: ([0-9.]+) s\s*$")
LEARNING_RATE = re.compile(rf"^{TS}: Current learning rate: ([0-9.eE+-]+)\s*$")


# ---------------------------------------------------------------- specs and paths

def dataset_name(dataset: str) -> str:
    return RUN["datasets"][dataset]["name"]


def plans_name(spec: Dict[str, Any]) -> str:
    return RUN["plans"][spec["plans"]]


def train_specs(include_conditional: bool = True) -> Dict[str, Dict[str, Any]]:
    runs = list(RUN["runs"]) + (list(RUN.get("conditional_runs", [])) if include_conditional else [])
    return {r["name"]: r for r in runs}


def smoke_specs() -> Dict[str, Dict[str, Any]]:
    return {r["name"]: r for r in RUN["smoke"]["runs"]}


def spec_of(stage: str, name: str) -> Dict[str, Any]:
    C.require(stage in STAGES, f"unknown stage {stage}")
    specs = smoke_specs() if stage == "smoke" else train_specs()
    C.require(name in specs, f"unknown {stage} run {name}")
    return specs[name]


def fold_of(stage: str, spec: Dict[str, Any]) -> int:
    return RUN["smoke"]["fold"] if stage == "smoke" else spec["fold"]


def run_dir(stage: str, name: str) -> Path:
    return C.ROOT / "results" / stage / name


def fold_dir(stage: str, spec: Dict[str, Any]) -> Path:
    return (run_dir(stage, spec["name"]) / "nnUNet_results" / dataset_name(spec["dataset"])
            / f"{spec['trainer']}__{plans_name(spec)}__{CONFIG}" / f"fold_{fold_of(stage, spec)}")


def checkpoint_final(stage: str, name: str) -> Path:
    return fold_dir(stage, spec_of(stage, name)) / "checkpoint_final.pth"


def val_count(stage: str, spec: Dict[str, Any]) -> int:
    if stage == "smoke":
        return len(smoke_val_cases(spec))
    if spec.get("cohort") == "ucsd":
        return len(cohort_val_cases(spec["fold"]))
    return RUN["fold_sizes"][spec["fold"]]


# ---------------------------------------------------------------- the M checkpoints (r5 package) and the case lists

def source_checkpoint(fold: int) -> Dict[str, Any]:
    """The fold's M after 1000 epochs in the r5 package: path and the SHA256 pinned in RUN.json. Read only."""
    source = RUN["source_package"]
    pin = source["runs"][str(fold)]
    root = Path(source["root"])
    path = (root / "results" / "train" / pin["run"] / "nnUNet_results" / dataset_name(source["dataset"])
            / f"{source['trainer']}__{RUN['plans'][source['plans']]}__{CONFIG}" / f"fold_{fold}" / "checkpoint_final.pth")
    return {"run": pin["run"], "path": path, "sha256": pin["checkpoint_sha256"], "epochs": source["epochs"],
            "record": root / "evidence" / pin["record"], "record_sha256": pin["record_sha256"],
            "validation": path.parent / "validation"}


def case_lists() -> Dict[str, Any]:
    return C.read_json(CASE_LISTS)


def cohort_val_cases(fold: int) -> List[str]:
    """The UCSD cases of the fold's validation part, as the preflight recorded them."""
    return case_lists()["ucsd_val_by_fold"][str(fold)]


def smoke_val_cases(spec: Dict[str, Any]) -> List[str]:
    """Validation cases of the CPU smoke, chosen by the preflight from the smoke fold's validation part: one UCSD case
    with a cavity and one case of another source. The UCSD-only arms must export the UCSD case alone."""
    chosen = case_lists()["smoke_val"]
    return sorted(chosen["ucsd"] if spec.get("cohort") == "ucsd" else chosen["ucsd"] + chosen["other"])


def rc_env(spec: Dict[str, Any], fold: int, checkpoint: Path) -> Dict[str, str]:
    """What the RC trainers read from the environment: the M checkpoint for every run; the case lists only for the
    arms that use them (B0' for the cavity cases, BU and BUL for the UCSD cases)."""
    source = source_checkpoint(fold)
    env = {"RC_SOURCE_CHECKPOINT": str(checkpoint), "RC_SOURCE_EPOCH": str(source["epochs"]),
           "RC_SOURCE_SHA256": source["sha256"]}
    if spec.get("case_lists"):
        env.update(RC_CASE_LISTS=str(CASE_LISTS), RC_CASE_LISTS_SHA256=C.sha256_file(CASE_LISTS))
    return env


def resources(spec: Dict[str, Any]) -> Dict[str, Any]:
    return RUN["resources"][spec["resources"]]


def evidence_name(stage: str, name: str, what: str, attempt: int = 0) -> str:
    tag = "" if attempt == 0 else f"_A{attempt}"
    return f"{'SMOKE' if stage == 'smoke' else 'RUN'}_{name}{tag}_{what}.json"


def source_run(spec: Dict[str, Any]) -> Optional[str]:
    return spec.get("pretrained_from") or spec.get("continue_from")


# ---------------------------------------------------------------- command and environment

def command(stage: str, spec: Dict[str, Any], resume: bool, pretrained: Optional[Path]) -> List[str]:
    cmd = [str(Path(RUN["environments"]["nnunet_bin"]) / "nnUNetv2_train"), spec["dataset"], CONFIG,
           str(fold_of(stage, spec)), "-tr", spec["trainer"], "-p", plans_name(spec), "-num_gpus", "1", "--npz"]
    if resume:
        cmd.append("--c")
    elif pretrained is not None:
        cmd += ["-pretrained_weights", str(pretrained)]
    if stage == "smoke":  # the CPU smoke; a real run never carries -device (nnU-Net's default is cuda)
        cmd += ["-device", "cpu"]
    return cmd


def job_env(base: Dict[str, str], stage: str, spec: Dict[str, Any], preprocessed: Path,
            continuation: Optional[Dict[str, str]] = None) -> Dict[str, str]:
    env = {k: v for k, v in base.items() if k not in P3_ENV and not k.startswith("nnUNet_")}
    env.update(RUN["environments"]["job_env"])
    cache = run_dir(stage, spec["name"]) / "cache"
    env.update({
        "nnUNet_raw": str(RAW_EMPTY),
        "nnUNet_preprocessed": str(preprocessed),
        "nnUNet_results": str(run_dir(stage, spec["name"]) / "nnUNet_results"),
        "nnUNet_extTrainer": str(EXT),
        "nnUNet_n_proc_DA": str(resources(spec)["n_proc_DA"]),
        # workers started with "spawn" (validation export) must be able to import the trainer module again; the
        # package's runtime folder (common.py, p3.py) is deliberately not on the training's path
        "PYTHONPATH": str(EXT),
        **{key: str(cache / key.lower()) for key in CACHE_KEYS},
    })
    if continuation:
        env.update(continuation)
    if stage == "smoke":
        env["P3_SMOKE_EPOCHS"] = str(spec["epochs"])
        env["RC_SMOKE_ITERATIONS"] = str(RUN["smoke"]["iterations"])
    return env


# ---------------------------------------------------------------- /dev/shm

def shm_root(job_id: str, tag: str = "") -> Path:
    return Path(RUN["shm"]["prefix"] + str(job_id) + tag)


def shm_job_id(name: str) -> Optional[int]:
    """Job id encoded in a /dev/shm entry made by this package (<prefix><job>[_tag]); None for anything else."""
    prefix = Path(RUN["shm"]["prefix"]).name
    if not name.startswith(prefix):
        return None
    digits = re.match(r"(\d+)", name[len(prefix):])
    return int(digits.group(1)) if digits else None


def stale_entries(names: Iterable[str], own_job: int, live_jobs: Iterable[int]) -> List[str]:
    """Our /dev/shm folders whose job is neither this one nor still known to slurm as alive."""
    live = set(live_jobs) | {own_job}
    return sorted(n for n in names if shm_job_id(n) is not None and shm_job_id(n) not in live)


def dataset_bytes(dataset: str) -> int:
    spec = RUN["datasets"]["265"]  # Dataset267 holds the same arrays; its .pkl files differ by a few bytes
    return spec["data_bytes"] + spec["gt_bytes"]


def copy_dataset(src: Path, dest: Path, threads: int, case_subset: Optional[Sequence[str]] = None) -> Dict[str, Any]:
    """Real copies (symlinks followed) of a preprocessed dataset, each file's size checked. With case_subset only those
    cases' data files are copied (cancel probe)."""
    C.require(not dest.exists(), f"copy target exists: {dest}")
    folders = sorted(p.name for p in src.iterdir() if p.is_dir())
    C.require(folders == sorted(SHM_DIRS), f"unexpected folders in {src}: {folders}")
    files = [p.name for p in src.iterdir() if p.is_file()]
    for folder in SHM_DIRS:
        (dest / folder).mkdir(parents=True)
        names = sorted(p.name for p in (src / folder).iterdir())
        if case_subset is not None:
            names = [n for n in names if n.split(".", 1)[0].replace("_seg", "") in set(case_subset)]
        files += [f"{folder}/{n}" for n in names]
    started = time.time()

    def one(relative: str) -> int:
        shutil.copyfile(src / relative, dest / relative)
        size = os.stat(src / relative).st_size
        C.require(os.stat(dest / relative).st_size == size, f"copy size mismatch: {relative}")
        return size

    pool = ThreadPoolExecutor(threads)
    try:
        total = sum(pool.map(one, files))
    finally:
        # on a cancel signal only the files already being copied finish; queued copies are dropped
        pool.shutdown(wait=True, cancel_futures=True)
    seconds = time.time() - started
    return {"files": len(files), "bytes": total, "seconds": seconds, "mb_per_s": total / 2 ** 20 / max(seconds, 1e-9)}


# ---------------------------------------------------------------- logs

def _stamp(line: str) -> Optional[float]:
    match = STAMP.match(line)
    if not match:
        return None
    text = match.group(1)
    return datetime.strptime(text, "%Y-%m-%d %H:%M:%S.%f" if "." in text else "%Y-%m-%d %H:%M:%S").timestamp()


def parse_training_logs(texts: Sequence[str]) -> Dict[str, Any]:
    """Epoch numbers, epoch times, learning rates and the final-validation duration from nnU-Net training_log_*.txt
    files (in time order)."""
    epochs, seconds, rates = [], [], []
    done_at = validated_at = None
    for text in texts:
        for line in text.splitlines():
            if EPOCH_START.match(line):
                epochs.append(int(EPOCH_START.match(line).group(2)))
            elif EPOCH_TIME.match(line):
                seconds.append(float(EPOCH_TIME.match(line).group(1)))
            elif LEARNING_RATE.match(line):
                rates.append(float(LEARNING_RATE.match(line).group(1)))
            elif line.rstrip().endswith(": Training done."):
                done_at = _stamp(line)
            elif line.rstrip().endswith(": Validation complete"):
                validated_at = _stamp(line)
    validation_s = validated_at - done_at if done_at is not None and validated_at is not None else None
    return {"epochs": epochs, "epoch_seconds": seconds, "learning_rates": rates, "training_done": done_at is not None,
            "validation_complete": validated_at is not None, "validation_seconds": validation_s}


def steady_median(epoch_seconds: Sequence[float], steady_from: int) -> Optional[float]:
    steady = list(epoch_seconds[steady_from:])
    return statistics.median(steady) if steady else None


def memory_peak(lines: Iterable[str]) -> Dict[str, Optional[float]]:
    import json

    records = [json.loads(line) for line in lines if line.strip()]
    if not records:
        return {"max_allocated_mib": None, "max_reserved_mib": None, "epochs_logged": 0}
    return {"max_allocated_mib": max(r["max_allocated_mib"] for r in records),
            "max_reserved_mib": max(r["max_reserved_mib"] for r in records), "epochs_logged": len(records)}


def gpu_util(text: str) -> Dict[str, Optional[float]]:
    """nvidia-smi --query-gpu=timestamp,uuid,utilization.gpu,memory.used,power.draw --format=csv,noheader,nounits"""
    util, used = [], []
    for line in text.splitlines():
        parts = [p.strip() for p in line.split(",")]
        if len(parts) != 5:
            continue
        try:
            util.append(float(parts[2]))
            used.append(float(parts[3]))
        except ValueError:
            continue
    return {"samples": len(util), "util_mean": statistics.fmean(util) if util else None,
            "mem_used_max_mib": max(used) if used else None}


def projected_hours(epoch_s: float, epochs: int, val_case_s: Optional[float], val_cases: int) -> float:
    return (epoch_s * epochs + (val_case_s or 0.0) * val_cases) / 3600


def cost_yuan(hours: float, cpus: int) -> Dict[str, float]:
    price = RUN["prices"]
    return {"gpu_only": hours * price["a100_card_hour_yuan"],
            "with_cpu": hours * (price["a100_card_hour_yuan"] + cpus * price["cpu_core_hour_yuan"])}


# ---------------------------------------------------------------- wave-2 dependency graph

def check_wave2_graph(runs: Sequence[Dict[str, Any]], slots: Sequence[Sequence[str]], max_concurrent: int) -> None:
    """Every dependency names an earlier run; the slots cover every run once and each slot member waits for the one
    before it, so no more than len(slots) runs can hold a GPU at the same time."""
    names = [r["name"] for r in runs]
    C.require(len(names) == len(set(names)), "duplicate run names")
    seen = set()
    for r in runs:
        for dep in r["after_ok"] + r["after_any"]:
            C.require(dep in seen, f"{r['name']} depends on {dep}, which is not submitted before it")
        source = source_run(r)
        if source:
            C.require(source in r["after_ok"], f"{r['name']} must wait (afterok) for its source run {source}")
        seen.add(r["name"])
    flat = [n for slot in slots for n in slot]
    C.require(sorted(flat) == sorted(names), "slots must cover every wave-2 run exactly once")
    C.require(len(slots) <= max_concurrent, "more slots than allowed concurrent GPUs")
    by_name = {r["name"]: r for r in runs}
    for slot in slots:
        for before, after in zip(slot, slot[1:]):
            deps = by_name[after]["after_ok"] + by_name[after]["after_any"]
            C.require(before in deps, f"{after} does not wait for {before} in its slot")


# ---------------------------------------------------------------- no-shm resubmission (r5)

LIVE = ("queued", "running")


def plan_noshm(runs: Sequence[Dict[str, Any]], name: str, status: Dict[str, str]):
    """What operator/submit.py noshm does after run `name` ended without /dev/shm space (status 'noshm').

    resubmit: `name` plus every run, in RUN.json order, that slurm cancelled before it started ('gone') because an
              afterok dependency is being resubmitted; their dependencies point to the new jobs, to runs still in the
              queue, and drop runs that already finished (afterok needs those to be 'complete').
    update:   runs still pending ('queued') with a dependency on a resubmitted run get their dependency list rewritten
              the same way, so the slot order (at most 8 GPUs) holds.
    Each entry is (run, after_ok run names, after_any run names)."""
    C.require(status.get(name) == "noshm", f"{name} did not end with a no-shm record")
    chosen: List[str] = []
    for r in runs:
        if r["name"] == name or (status.get(r["name"]) == "gone" and any(d in chosen for d in r["after_ok"])):
            chosen.append(r["name"])

    def deps(r: Dict[str, Any]):
        ok = []
        for d in r["after_ok"]:
            if d in chosen or status.get(d) in LIVE:
                ok.append(d)
            else:
                C.require(status.get(d) == "complete", f"{r['name']} needs {d}, which is {status.get(d)}")
        any_ = [d for d in r["after_any"] if d in chosen or status.get(d) in LIVE]
        return r["name"], ok, any_

    resubmit = [deps(r) for r in runs if r["name"] in chosen]
    update = [deps(r) for r in runs if r["name"] not in chosen and status.get(r["name"]) == "queued"
              and any(d in chosen for d in r["after_ok"] + r["after_any"])]
    return resubmit, update

"""One nnU-Net training run of this package on one A100.

Derived from s2_p3_wave2_20261104_r5/runtime/launch_run.py (the launcher of M, L and LES). Changed for the RC
training comparison:
- gate: PREFLIGHT pass, SMOKE_COMPLETE pass (here the CPU smoke of the five trainers), the case lists unchanged
  since the preflight, and the fold's M record in the r5 package (pinned, read only) instead of a run of this package;
- run_training: every run gets the M checkpoint of its fold (SHA256 checked against RUN.json) and, where the arm
  uses them, the case lists, through the environment (p3.rc_env); no -pretrained_weights, no continuation;
- verify_outputs: the trainer's record of the loaded weights, the first learning rate, the sampling record (B0p),
  the validation cases (BU, BUL: exactly the fold's UCSD cases); then the intermediate checkpoints named in RUN.json
  delete_after_success are removed (only after every check passed);
- RUN.json shm.wait_max_s is 20 minutes here (r5: 2 hours);
- the smoke stage is the CPU smoke (cpu_smoke.py uses run_training and verify_outputs of this file): no GPU
  monitor and no CUDA memory log when no GPU is given, the smoke split validates the two cases the preflight chose.
The /dev/shm smoke-split and cancel-probe code of r5 is left in place and is not used by any job of this package.

Real run (slurm/30_train.slurm execs this):  launch_run.py --run NAME [--resume]
    1. checks: package manifest, PREFLIGHT pass (it pins Dataset268 and writes the case lists), SMOKE_COMPLETE pass,
       the fold's M record and checkpoint in the r5 package, no STARTED record yet for this attempt,
       exactly one A100 visible;
    2. removes /dev/shm folders of this package whose slurm job no longer exists (a SIGKILLed job cannot clean up);
    3. storage (r5), before anything is recorded as started: waits up to shm.wait_max_s (20 min) for enough free /dev/shm
       (other users' jobs fill it; slurm cannot see it), then copies the dataset to <shm.prefix><job> in /dev/shm and checks the
       pinned files. Still too full after the wait (or full during the copy): runs with nfs_fallback (the lesion member)
       read the dataset from NFS through a view (step 3b); every other run writes RUN_<name>_NOSHM_<job>.json and exits
       with shm.noshm_exit_code, leaving no STARTED record, so operator/submit.py noshm can submit it again on another
       node (user's standing approval: at most shm.max_noshm_resubmits times per run);
    3b. NFS view: results/<stage>/nfs_views/<name>_a<attempt>/nnUNet_preprocessed/<dataset>/ with copies of the
       top-level JSON files and symlinks to the dataset's data and gt folders (nothing is written to the shared tree);
    4. writes the exclusive STARTED record, so the same run (attempt) cannot start twice;
    5. runs nnUNetv2_train in its own session (trainer, plans, fold, --npz) while sampling GPU and CPU use;
    6. checks the outputs: checkpoint_final epoch and trainer, validation summary, one .nii.gz/.npz/.pkl per validation
       case, the CUDA memory log, the trainer's record of the loaded M weights, the first learning rate, and (r3) the
       label round trip with the dataset.json and plans.json nnU-Net saved next to the model (what inference will use);
    7. always: SIGTERM to the training's process group, the /dev/shm copy removed, a COMPLETE / FAILED / CANCELLED record.
    SIGTERM / SIGINT / SIGHUP (scancel, time limit) jump to step 7; KillWait on this cluster is 30 s.
    --resume (operator/resume.sh, only with the user's approval): next attempt of a FAILED or CANCELLED run in the same
    results folder, with nnU-Net's --c when the run left a checkpoint.

Probe (smoke only):  launch_run.py --probe JOBTAG — the /dev/shm copy (20 cases) and step 7 around a sleeping child,
so smoke.py can signal it the way scancel does and check that the copy is gone.
"""

from __future__ import annotations

import argparse
import errno
import os
import shutil
import signal
import subprocess
import sys
import threading
import time
import traceback
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

import common as C
import p3 as P
import roundtrip

RUN = P.RUN
HANDLED = (signal.SIGTERM, signal.SIGINT, signal.SIGHUP)


class Cancelled(Exception):
    pass


class NoShm(Exception):
    """/dev/shm stayed too full for the whole wait, or filled up during the copy."""


class Guard:
    """The first termination signal becomes Cancelled in the main thread; once cleanup starts, signals are ignored so
    that the cleanup itself cannot be interrupted."""

    def __init__(self) -> None:
        self.received: Optional[str] = None
        self.cleaning = False
        for sig in HANDLED:
            signal.signal(sig, self.handle)

    def handle(self, signum, frame) -> None:
        if self.received is None:
            self.received = signal.Signals(signum).name
        if not self.cleaning:
            raise Cancelled(self.received)

    def begin_cleanup(self) -> None:
        self.cleaning = True
        for sig in HANDLED:
            signal.signal(sig, signal.SIG_IGN)


# ---------------------------------------------------------------- node, GPU, monitors

def gpu_identity() -> Dict[str, str]:
    visible = os.environ.get("CUDA_VISIBLE_DEVICES", "")
    C.require(visible != "" and "," not in visible, f"expected one visible GPU, CUDA_VISIBLE_DEVICES={visible!r}")
    out = subprocess.run(["nvidia-smi", "--query-gpu=index,name,uuid", "--format=csv,noheader"], capture_output=True,
                         text=True, timeout=120).stdout
    rows = [line.split(", ") for line in out.splitlines() if line.strip()]
    mine = rows if len(rows) == 1 else [r for r in rows if r[0] == visible]
    C.require(len(mine) == 1 and "A100" in mine[0][1], f"cannot identify one A100: {out}")
    return {"index": mine[0][0], "name": mine[0][1], "uuid": mine[0][2], "cuda_visible_devices": visible,
            "node": os.environ.get("SLURMD_NODENAME", ""), "affinity": sorted(os.sched_getaffinity(0))}


def start_gpu_monitor(path: Path, uuid: str, interval: int) -> subprocess.Popen:
    handle = path.open("w", encoding="utf-8")
    return subprocess.Popen(["nvidia-smi", "-i", uuid, "--query-gpu=timestamp,uuid,utilization.gpu,memory.used,power.draw",
                             "--format=csv,noheader,nounits", "-l", str(interval)], stdout=handle,
                            stderr=subprocess.STDOUT, start_new_session=True)


class CpuSampler(threading.Thread):
    """CPU seconds of every process in the training's session (trainer, augmentation workers, export pool)."""

    def __init__(self, session: int, interval: float):
        super().__init__(daemon=True)
        self.session, self.interval = session, interval
        self.tick = os.sysconf("SC_CLK_TCK")
        self.stop = threading.Event()
        self.last: Dict[int, int] = {}
        self.series: List[List[float]] = []

    def sample(self) -> None:
        for entry in os.scandir("/proc"):
            if not entry.name.isdigit():
                continue
            try:
                with open(f"/proc/{entry.name}/stat") as handle:
                    head, _, tail = handle.read().rpartition(")")
                fields = tail.split()
                if int(fields[3]) == self.session:
                    self.last[int(entry.name)] = int(fields[11]) + int(fields[12])
            except (OSError, ValueError, IndexError):
                continue
        self.series.append([time.time(), sum(self.last.values()) / self.tick, len(self.last)])

    def run(self) -> None:
        while not self.stop.is_set():
            self.sample()
            self.stop.wait(self.interval)

    def cores(self) -> Optional[float]:
        if len(self.series) < 2 or self.series[-1][0] <= self.series[0][0]:
            return None
        return (self.series[-1][1] - self.series[0][1]) / (self.series[-1][0] - self.series[0][0])


# ---------------------------------------------------------------- /dev/shm

def sweep_stale(own_job: str) -> Dict[str, Any]:
    """Remove /dev/shm folders of this package (owned by us) whose slurm job is gone. Nothing is removed when squeue
    cannot be read."""
    shm = Path("/dev/shm")
    ours = sorted(e.name for e in os.scandir(shm) if P.shm_job_id(e.name) is not None
                  and e.stat(follow_symlinks=False).st_uid == os.getuid())
    query = subprocess.run(["squeue", "-h", "-o", "%A"], capture_output=True, text=True, timeout=120)
    if query.returncode != 0:
        return {"ours": ours, "removed": [], "skipped": f"squeue exited {query.returncode}"}
    live = [int(x) for x in query.stdout.split() if x.isdigit()]
    removed = []
    for name in P.stale_entries(ours, int(own_job), live):
        shutil.rmtree(shm / name, ignore_errors=True)
        removed.append({"name": name, "removed": not (shm / name).exists()})
    return {"ours": ours, "removed": removed}


def pinned_top_files(dataset: str) -> Dict[str, str]:
    return RUN["datasets"][dataset]["top_level_files_sha256"]  # 267 built by r2, 268 by r4; checked by the preflight


def write_smoke_split(dest: Path) -> Dict[str, Any]:
    """The smoke trains on the real fold-0 training cases and validates only the first few fold-0 validation cases."""
    splits = C.read_json(dest / "splits_final.json")
    os.remove(dest / "splits_final.json")  # our own copy in /dev/shm
    return _smoke_split(splits, dest)


def write_smoke_split_from(src: Path, dest: Path) -> Dict[str, Any]:
    return _smoke_split(C.read_json(src / "splits_final.json"), dest)


def _smoke_split(splits: List[Dict[str, Any]], dest: Path) -> Dict[str, Any]:
    fold = RUN["smoke"]["fold"]
    chosen = P.case_lists()["smoke_val"]  # one UCSD case with a cavity, one case of another source (preflight)
    val = sorted(chosen["ucsd"] + chosen["other"])
    C.require(set(val) <= set(splits[fold]["val"]) and len(val) == len(set(val)),
              "the smoke validation cases are not in the smoke fold's validation part")
    smoke = [{"train": sorted(splits[fold]["train"]), "val": val}]
    C.write_json(dest / "splits_final.json", smoke, mode=0o640)
    return {"train": len(smoke[0]["train"]), "val": smoke[0]["val"], "sha256": C.sha256_file(dest / "splits_final.json")}


def wait_for_shm(need_gb: float) -> Dict[str, Any]:
    """Poll /dev/shm until need + margin GB are free; NoShm after shm.wait_max_s. A cancel signal ends the sleep."""
    spec = RUN["shm"]
    started, checks, lowest = time.time(), 0, None
    while True:
        free_gb = shutil.disk_usage("/dev/shm").free / 2 ** 30
        checks += 1
        lowest = free_gb if lowest is None else min(lowest, free_gb)
        waited = time.time() - started
        if free_gb >= need_gb + spec["free_margin_gb"]:
            return {"free_gb": free_gb, "waited_s": waited, "checks": checks, "lowest_free_gb": lowest}
        if waited >= spec["wait_max_s"]:
            raise NoShm(f"/dev/shm has {free_gb:.0f} GB free after waiting {waited:.0f} s; need {need_gb:.0f} GB "
                        f"+ {spec['free_margin_gb']} GB margin (lowest seen {lowest:.0f} GB, {checks} checks)")
        time.sleep(spec["wait_poll_s"])


def prepare_shm(stage: str, dataset: str, root: Path, case_subset: Optional[List[str]] = None) -> Dict[str, Any]:
    spec = RUN["shm"]
    C.require(str(root).startswith(spec["prefix"]), f"unexpected shm path {root}")
    need_gb = P.dataset_bytes(dataset) / 2 ** 30 if case_subset is None else 1.0
    mem_gb = int(os.environ.get("SLURM_MEM_PER_NODE", "0")) / 1024
    C.require(mem_gb >= need_gb + spec["mem_headroom_gb"], f"job memory {mem_gb:.0f} GB too small for the copy")
    wait = wait_for_shm(need_gb)
    dest = root / "nnUNet_preprocessed" / P.dataset_name(dataset)
    try:
        info = P.copy_dataset(P.PRE / P.dataset_name(dataset), dest, spec["copy_threads"], case_subset)
    except OSError as error:
        if error.errno != errno.ENOSPC:
            raise
        shutil.rmtree(root, ignore_errors=True)
        raise NoShm(f"/dev/shm filled up during the copy: {error!r}") from error
    info.update(free_gb_before=wait["free_gb"], shm_wait=wait, path=str(dest), mode="shm")
    for name, digest in pinned_top_files(dataset).items():
        C.require(C.sha256_file(dest / name) == digest, f"{name} in the /dev/shm copy differs from its pin")
    if stage == "smoke":
        info["smoke_split"] = write_smoke_split(dest)
    return info


def prepare_nfs_view(stage: str, spec: Dict[str, Any], attempt: int) -> Tuple[Path, Dict[str, Any]]:
    """nnUNet_preprocessed view on NFS: copied top-level JSON files, symlinks to the shared data and gt folders."""
    view = C.ROOT / "results" / stage / "nfs_views" / f"{spec['name']}_a{attempt}" / "nnUNet_preprocessed"
    src, dest = P.PRE / P.dataset_name(spec["dataset"]), view / P.dataset_name(spec["dataset"])
    C.require(not dest.exists(), f"NFS view exists: {dest}")
    dest.mkdir(parents=True)
    for path in src.iterdir():
        if path.is_file():
            with (dest / path.name).open("xb") as handle:
                handle.write(path.read_bytes())
    for folder in P.SHM_DIRS:
        os.symlink(src / folder, dest / folder)
    for name, digest in pinned_top_files(spec["dataset"]).items():
        C.require(C.sha256_file(dest / name) == digest, f"{name} in the NFS view differs from its pin")
    info: Dict[str, Any] = {"mode": "nfs", "path": str(dest)}
    if stage == "smoke":
        os.remove(dest / "splits_final.json")  # the view's own copy
        info["smoke_split"] = write_smoke_split_from(src, dest)
    return view, info


def acquire_storage(stage: str, spec: Dict[str, Any], root: Path, attempt: int) -> Tuple[Path, Dict[str, Any]]:
    """/dev/shm copy (waiting for space), NFS view for storage == nfs (smoke test of the fallback), or NFS view after
    NoShm for nfs_fallback runs. NoShm propagates for every other run."""
    if spec.get("storage") == "nfs":
        return prepare_nfs_view(stage, spec, attempt)
    try:
        return root / "nnUNet_preprocessed", prepare_shm(stage, spec["dataset"], root)
    except NoShm as error:
        if not spec.get("nfs_fallback"):
            raise
        view, info = prepare_nfs_view(stage, spec, attempt)
        return view, dict(info, mode="nfs_fallback", shm_error=str(error))


def shared_data_untouched(dataset: str) -> Dict[str, Any]:
    """After a run that read the shared tree through an NFS view: the data and gt folders still hold exactly the
    expected entries (Dataset268: symlinks only)."""
    folder = P.PRE / P.dataset_name(dataset)
    out = {}
    for sub, expected in ((P.DATA_ID, 3 * RUN["datasets"][dataset]["cases"]),
                          ("gt_segmentations", RUN["datasets"][dataset]["cases"])):
        entries = list(os.scandir(folder / sub))
        out[sub] = len(entries)
        C.require(len(entries) == expected, f"{sub} of {dataset} has {len(entries)} entries, expected {expected}")
        if dataset == "268":
            C.require(all(e.is_symlink() for e in entries), f"{sub} of Dataset268 holds a non-link entry")
    return out


def stop_child(proc: Optional[subprocess.Popen], grace: float) -> Optional[int]:
    if proc is None:
        return None
    for sig, wait in ((signal.SIGTERM, grace), (signal.SIGKILL, 10)):
        try:
            os.killpg(proc.pid, sig)  # the whole session: augmentation workers and export pool included
        except ProcessLookupError:
            pass
        try:
            proc.wait(timeout=wait)
            break
        except subprocess.TimeoutExpired:
            continue
    return proc.returncode


def cleanup(holder: Dict[str, Any], roots: List[Path]) -> Dict[str, Any]:
    """Order matters within KillWait: signal the training, free the RAM, then wait for the processes."""
    started = time.time()
    proc = holder.get("proc")
    if proc is not None and proc.poll() is None:
        try:
            os.killpg(proc.pid, signal.SIGTERM)
        except ProcessLookupError:
            pass
    removed = {}
    for root in roots:
        for _ in range(2):
            shutil.rmtree(root, ignore_errors=True)
            if not root.exists():
                break
        removed[str(root)] = not root.exists()
    out = {"shm_removed": removed, "shm_removed_after_s": time.time() - started,
           "child_returncode": stop_child(proc, RUN["shm"]["child_grace_s"])}
    for key in ("monitor",):
        if holder.get(key) is not None:
            stop_child(holder[key], 2)
    if holder.get("sampler") is not None:
        holder["sampler"].stop.set()
    out["seconds"] = time.time() - started
    return out


# ---------------------------------------------------------------- one training

def gate(stage: str, spec: Dict[str, Any]) -> str:
    manifest = C.verify_manifest()
    pre = C.read_json(C.ROOT / "evidence" / "PREFLIGHT.json")
    C.require(pre["status"] == "pass" and pre["manifest_sha256"] == manifest, "preflight did not pass for this manifest")
    if stage == "train":
        smoke = C.read_json(C.ROOT / "evidence" / "SMOKE_COMPLETE.json")
        C.require(smoke["status"] == "pass" and smoke["manifest_sha256"] == manifest, "smoke did not pass")
    C.require(C.sha256_file(P.CASE_LISTS) == pre["case_lists"]["sha256"], "case lists changed since the preflight")
    source = P.source_checkpoint(P.fold_of(stage, spec))
    C.require(C.sha256_file(Path(RUN["source_package"]["root"]) / "MANIFEST.sha256") == RUN["source_package"]["manifest_sha256"],
              "the r5 package's manifest differs from its pin")
    C.require(C.sha256_file(source["record"]) == source["record_sha256"], f"r5 record of {source['run']} differs from its pin")
    C.require(C.read_json(source["record"])["status"] == "pass", f"r5 run {source['run']} did not complete")
    return manifest


def run_training(stage: str, spec: Dict[str, Any], preprocessed: Path, attempt: int, resume: bool,
                 holder: Dict[str, Any], gpu: Optional[Dict[str, str]], cores: Optional[List[int]] = None) -> Dict[str, Any]:
    rdir = P.run_dir(stage, spec["name"])
    C.require(attempt > 0 or not rdir.exists(), f"results folder already exists: {rdir}")
    rdir.mkdir(parents=True, exist_ok=attempt > 0)
    record: Dict[str, Any] = {}
    source = P.source_checkpoint(P.fold_of(stage, spec))
    C.require(source["path"].is_file(), f"M checkpoint missing: {source['path']}")
    digest = C.sha256_file(source["path"])
    C.require(digest == source["sha256"], f"M checkpoint of {source['run']} differs from its pin")
    record["source"] = {"run": source["run"], "checkpoint": str(source["path"]), "sha256": digest}
    fold = P.fold_dir(stage, spec)
    use_c = resume and any((fold / f).is_file() for f in ("checkpoint_latest.pth", "checkpoint_final.pth"))
    cmd = P.command(stage, spec, use_c, None)
    if cores:
        cmd = ["taskset", "-c", ",".join(str(c) for c in cores)] + cmd
    env = P.job_env(dict(os.environ), stage, spec, preprocessed, P.rc_env(spec, P.fold_of(stage, spec), source["path"]))
    for key in P.CACHE_KEYS:
        Path(env[key]).mkdir(parents=True, exist_ok=True)
    P.RAW_EMPTY.mkdir(parents=True, exist_ok=True)
    if gpu is not None:  # None: the CPU smoke
        holder["monitor"] = start_gpu_monitor(rdir / f"gpu_a{attempt}.csv", gpu["uuid"], RUN["monitor"]["gpu_interval_s"])
    record.update(command=cmd, used_resume_flag=use_c, cores=cores,
                  env={k: env[k] for k in sorted(env) if k.startswith(("nnUNet_", "P3_", "RC_", "OMP_", "PYTHONPATH"))})
    started = time.time()
    with (rdir / f"stdout_a{attempt}.log").open("w", encoding="utf-8") as log:
        proc = subprocess.Popen(cmd, env=env, stdout=log, stderr=subprocess.STDOUT, cwd=rdir, start_new_session=True)
        holder["proc"] = proc
        sampler = CpuSampler(proc.pid, RUN["monitor"]["cpu_sample_s"])
        holder["sampler"] = sampler
        sampler.start()
        while proc.poll() is None:
            time.sleep(2)
        sampler.stop.set()
        sampler.join()
        sampler.sample()
    record.update(returncode=proc.returncode, wall_s=time.time() - started, cpu_cores_mean=sampler.cores())
    stop_child(proc, 5)  # stray workers of a finished training, if any
    stop_child(holder.pop("monitor", None), 2)
    return record


def verify_outputs(stage: str, spec: Dict[str, Any], attempt: int, storage_mode: str = "shm") -> Dict[str, Any]:
    import torch

    fold = P.fold_dir(stage, spec)
    checkpoint = torch.load(fold / "checkpoint_final.pth", map_location="cpu", weights_only=False)
    out: Dict[str, Any] = {"checkpoint_epoch": checkpoint["current_epoch"], "checkpoint_trainer": checkpoint["trainer_name"],
                           "checkpoint_sha256": C.sha256_file(fold / "checkpoint_final.pth")}
    C.require(checkpoint["current_epoch"] == spec["epochs"], f"checkpoint epoch {checkpoint['current_epoch']}")
    C.require(checkpoint["trainer_name"] == spec["trainer"], f"checkpoint trainer {checkpoint['trainer_name']}")
    validation, n = fold / "validation", P.val_count(stage, spec)
    counts = {ext: len(list(validation.glob(f"*{ext}"))) for ext in (".nii.gz", ".npz", ".pkl")}
    out["validation_files"] = counts
    C.require(all(v == n for v in counts.values()), f"validation files {counts}, expected {n} each")
    summary = C.read_json(validation / "summary.json")  # nnU-Net writes NaN for a region absent from every case
    dice = {"foreground_mean": summary["foreground_mean"]["Dice"],
            "per_class_or_region": {k: v["Dice"] for k, v in summary["mean"].items()}}
    out["nnunet_validation_dice"] = C.finite(dice)
    out["nnunet_dice_undefined"] = sorted(k for k, v in dice["per_class_or_region"].items() if v != v)
    out["nnunet_n_pred_n_ref"] = {k: [v["n_pred"], v["n_ref"]] for k, v in summary["mean"].items()}
    out["label_roundtrip"] = model_label_roundtrip(spec, fold.parent)
    logs = P.parse_training_logs([p.read_text(encoding="utf-8") for p in sorted(fold.glob("training_log_*.txt"))])
    C.require(logs["training_done"] and logs["validation_complete"], "training log incomplete")
    out["log"] = {"epochs_logged": len(logs["epoch_seconds"]), "learning_rate_first": logs["learning_rates"][:1],
                  "learning_rate_last": logs["learning_rates"][-1:], "validation_seconds": logs["validation_seconds"],
                  "epoch_seconds": logs["epoch_seconds"]}
    if stage == "train":
        with (fold / "p3_cuda_memory.jsonl").open(encoding="utf-8") as handle:
            out["cuda_memory"] = P.memory_peak(handle)
    else:  # the CPU smoke: the trainer writes this log on CUDA only
        C.require(not (fold / "p3_cuda_memory.jsonl").exists(), "a CUDA memory log in the CPU smoke")
        out["cuda_memory"] = None
    source = P.source_checkpoint(P.fold_of(stage, spec))
    audit = C.read_json(fold / "rc_source_weights.json")
    C.require(audit["sha256"] == source["sha256"] and audit["source_epoch"] == source["epochs"]
              and audit["optimizer"] == "new" and audit["keys_loaded"] > 0, f"record of the loaded weights: {audit}")
    out["source_weights"] = audit
    C.require(logs["learning_rates"][:1] == [RUN["fine_tune"]["initial_lr"]], f"first learning rate {logs['learning_rates'][:1]}")
    if spec["trainer"] == RUN["fine_tune"]["sampling_trainer"]:
        sampling = C.read_json(fold / "rc_sampling.json")
        C.require(sampling["weight"] == RUN["fine_tune"]["rc_weight"] and sampling["heavy_cases"] > 0
                  and sampling["share_weighted"] > sampling["share_natural"], f"sampling record: {sampling}")
        out["sampling"] = sampling
    exported = sorted(p.name[:-len(".nii.gz")] for p in validation.glob("*.nii.gz"))
    if stage == "smoke":
        C.require(exported == P.smoke_val_cases(spec), f"smoke validation cases {exported}")
        out["validation_cases"] = exported
    elif spec.get("cohort") == "ucsd":
        C.require(exported == sorted(P.cohort_val_cases(spec["fold"])), "validation cases are not the fold's UCSD cases")
        out["validation_cohort"] = {"cohort": "ucsd", "cases": len(exported)}
    if storage_mode != "shm":
        out["shared_data_untouched"] = shared_data_untouched(spec["dataset"])
    if stage == "train":  # last, after every check: only the final weights are kept (plan v3 section 5.7)
        removed = {}
        for name in RUN["delete_after_success"]:
            C.require(name != "checkpoint_final.pth" and "/" not in name, f"refusing to delete {name}")
            if (fold / name).is_file():
                removed[name] = (fold / name).stat().st_size
                (fold / name).unlink()
        out["intermediate_checkpoints_removed"] = removed
    return out


def model_label_roundtrip(spec: Dict[str, Any], model_dir: Path) -> Dict[str, Any]:
    """The dataset.json / plans.json nnU-Net saved next to the model must carry the dataset's label order and pass the
    label round trip on the preflight's cases (r2: Dataset265's sorted keys scrambled every exported region map)."""
    saved, used = C.read_json(model_dir / "dataset.json"), C.read_json(P.PRE / P.dataset_name(spec["dataset"]) / "dataset.json")
    C.require(list(saved["labels"].items()) == list(used["labels"].items())
              and saved.get("regions_class_order") == used.get("regions_class_order"),
              "the model's dataset.json differs from the dataset's (labels or their order)")
    cases = C.read_json(C.ROOT / "evidence" / "PREFLIGHT.json")["label_roundtrip"]["cases"]
    result = roundtrip.check(saved, C.read_json(model_dir / "plans.json"),
                             P.PRE / P.dataset_name(spec["dataset"]) / P.DATA_ID, cases)
    C.require(result["passed"], f"label round trip failed with the model's dataset.json: {result}")
    return result


# ---------------------------------------------------------------- entry points

def attempts_so_far(name: str) -> int:
    n = 0
    while (C.ROOT / "evidence" / P.evidence_name("train", name, "STARTED", n)).exists():
        n += 1
    return n


def main_train(name: str, resume: bool) -> int:
    spec = P.spec_of("train", name)
    attempt = attempts_so_far(name) if resume else 0
    if resume:
        C.require(attempt > 0, f"{name} never started; submit it normally")
        previous = C.ROOT / "evidence"
        C.require(not (previous / P.evidence_name("train", name, "COMPLETE", attempt - 1)).exists(), "already complete")
        C.require(any((previous / P.evidence_name("train", name, what, attempt - 1)).exists()
                      for what in ("FAILED", "CANCELLED")), "previous attempt has no FAILED or CANCELLED record")
    job = os.environ["SLURM_JOB_ID"]
    manifest = gate("train", spec)
    started_name = P.evidence_name("train", name, "STARTED", attempt)
    C.require(not (C.ROOT / "evidence" / started_name).exists(), f"{started_name} exists")
    gpu = gpu_identity()
    guard, holder = Guard(), {}
    root = P.shm_root(job)
    pre: Dict[str, Any] = {"run": name, "attempt": attempt, "gpu": gpu, "manifest_sha256": manifest,
                           "started_utc": C.utc_now()}
    try:  # r5: storage before the STARTED record, so a node without /dev/shm space leaves the attempt unused
        pre["sweep"] = sweep_stale(job)
        preprocessed, pre["storage"] = acquire_storage("train", spec, root, attempt)
    except (NoShm, Cancelled, Exception) as error:
        guard.begin_cleanup()
        pre.update(error=repr(error), traceback=traceback.format_exc(), cleanup=cleanup(holder, [root]),
                   ended_utc=C.utc_now())
        kind = "NOSHM" if isinstance(error, NoShm) else "PRESTART_CANCELLED" if isinstance(error, Cancelled) \
            else "PRESTART_FAILED"
        C.evidence(f"RUN_{name}_{kind}_{job}.json", kind.lower(), node=gpu["node"], **pre)
        return RUN["shm"]["noshm_exit_code"] if kind == "NOSHM" else 1
    record: Dict[str, Any] = dict(pre, spec=spec)
    status = "failed"
    try:  # STARTED inside the try: a signal right after it still reaches the cleanup below
        C.evidence(started_name, "started", manifest_sha256=manifest, spec=spec, gpu=gpu, resume=resume,
                   storage=pre["storage"])  # exclusive: a second start of this attempt fails here
        record["training"] = run_training("train", spec, preprocessed, attempt, resume, holder, gpu)
        if record["training"]["returncode"] == 0:
            record["outputs"] = verify_outputs("train", spec, attempt, pre["storage"]["mode"])
            status = "complete"
        else:
            record["error"] = f"nnUNetv2_train exited {record['training']['returncode']}"
    except Cancelled as signal_name:
        status, record["signal"] = "cancelled", str(signal_name)
    except Exception as error:  # recorded; the job fails and afterok dependants are cancelled by slurm
        record.update(error=repr(error), traceback=traceback.format_exc())
    finally:
        guard.begin_cleanup()
        record["cleanup"] = cleanup(holder, [root])
        record["ended_utc"] = C.utc_now()
        what = {"complete": "COMPLETE", "cancelled": "CANCELLED"}.get(status, "FAILED")
        C.evidence(P.evidence_name("train", name, what, attempt), "pass" if status == "complete" else status, **record)
    return 0 if status == "complete" else 1


def main_probe(tag: str) -> int:
    """Copy 20 cases to /dev/shm, start a sleeping child in its own session, wait for a signal, clean up."""
    job = os.environ["SLURM_JOB_ID"]
    guard, holder = Guard(), {}
    root = P.shm_root(job, tag)
    out_dir = C.ROOT / "results" / "smoke" / "cancel_probe"
    record: Dict[str, Any] = {"root": str(root), "started_utc": C.utc_now()}
    status = "failed"
    try:
        splits = C.read_json(P.PRE / P.dataset_name("265") / "splits_final.json")
        cases = sorted(splits[0]["val"])[: RUN["smoke"]["cancel_probe"]["cases"]]
        record["shm_copy"] = prepare_shm("probe", "265", root, case_subset=cases)
        holder["proc"] = subprocess.Popen([sys.executable, "-c", f"import time; time.sleep({RUN['smoke']['cancel_probe']['sleep_s']})"],
                                          start_new_session=True)
        C.write_json(out_dir / "PROBE_READY.json", {"probe_pid": os.getpid(), "child_pid": holder["proc"].pid,
                                                    "root": str(root)})
        holder["proc"].wait()
        record["error"] = "the sleeping child ended without a signal"
    except Cancelled as signal_name:
        status, record["signal"] = "cancelled", str(signal_name)
    except Exception as error:
        record.update(error=repr(error), traceback=traceback.format_exc())
    finally:
        guard.begin_cleanup()
        record["cleanup"] = cleanup(holder, [root])
        record["ended_utc"] = C.utc_now()
        C.write_json(out_dir / "PROBE_RESULT.json", dict(record, status=status))
    return 143 if status == "cancelled" else 1


def main() -> None:
    parser = argparse.ArgumentParser()
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("--run")
    group.add_argument("--probe")
    parser.add_argument("--resume", action="store_true")
    args = parser.parse_args()
    sys.exit(main_probe(args.probe) if args.probe else main_train(args.run, args.resume))


if __name__ == "__main__":
    main()
